<script setup>
import UserAvatar from '@/Components/Account/UserAvatar.vue';
import ListingReviews from '@/Components/Marketplace/ListingReviews.vue';
import { Head, Link, usePage, useForm } from '@inertiajs/vue3';
import Layout from '@/Layouts/MarketplaceLayout.vue';
import DiscoveryMap from '@/Components/Marketplace/DiscoveryMap.vue';
import ListingGallery from '@/Components/Marketplace/ListingGallery.vue';
defineProps({listing:Object,engagement:Object});const page=usePage();const save=useForm({});
const money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n);
</script>
<template><Layout><Head :title="listing.title"/><main class="content detail"><Link :href="`/explore?service=${listing.service}`" class="text-button">← Back to explore</Link><p class="eyebrow">{{ listing.service==='haul'?'AADI VEHICLES':listing.service==='raketeer'?'AADI RAKETS':'AADI SPACES' }}</p><h1>{{ listing.title }}</h1><p>{{ listing.location.address }}</p><div class="detail-grid"><section><ListingGallery :photos="listing.photos" :title="listing.title" :service="listing.service" :type="listing.type"/><h2>About this listing</h2><p class="description">{{ listing.description }}</p><h2>Details & features</h2><ul class="listing-features"><li v-for="feature in listing.comparison?.features" :key="feature">{{ feature }}</li><li v-if="listing.comparison?.scope">{{ listing.comparison.scope }}</li><li v-for="(value,key) in listing.details" :key="key"><template v-if="value">{{ key }}: {{ value }}</template></li></ul><p v-if="!listing.comparison?.features?.length && !listing.comparison?.scope && !Object.keys(listing.details || {}).length">No additional features provided.</p><h2>Location</h2><DiscoveryMap v-if="listing.location.lat!=null && listing.location.lng!=null" :listings="[listing]" :center="[listing.location.lat,listing.location.lng]"/><p v-else>Map location has not been provided.</p><ListingReviews :listing="listing" :engagement="engagement"/></section><aside class="detail-aside"><p class="large-price">{{ money(listing.price) }} <small>/ {{ listing.priceUnit }}</small></p><button type="button" class="button save-listing" :aria-pressed="engagement.saved" :disabled="save.processing" @click="engagement.saved ? save.delete(`/offers/${listing.service}/${listing.id}/save`,{preserveScroll:true}) : save.put(`/offers/${listing.service}/${listing.id}/save`,{preserveScroll:true})"><svg viewBox="0 0 24 24" aria-hidden="true" :fill="engagement.saved ? 'currentColor' : 'none'"><path d="M6 3h12v18l-6-4-6 4z"/></svg>{{ engagement.saved ? 'Saved listing' : 'Save listing' }}</button><hr/><p class="eyebrow">LISTED BY</p><UserAvatar :user="{name:listing.ownerName,avatar_url:listing.ownerAvatarUrl}"/><h2>{{ listing.ownerName }}</h2><p v-if="listing.providerApproved" class="provider-badge" title="An admin approved this provider’s role documents. This does not verify this individual listing.">✓ Provider role approved</p><p v-if="listing.ownerBio">{{ listing.ownerBio }}</p><p>Status: {{ listing.status }}</p><Link v-if="page.props.auth?.user?.id===listing.ownerId || page.props.auth?.user?.is_admin" :href="`/my-listings/${listing.service}/${listing.id}/edit`" class="button primary">Edit listing</Link><p v-else class="muted">Browse the details and location. Booking and messaging are not available yet.</p></aside></div></main></Layout></template>

<style scoped>
.save-listing{display:flex;gap:8px;align-items:center;width:100%;justify-content:center;margin:16px 0}.save-listing svg{width:20px;height:20px;stroke:currentColor;stroke-width:1.6}.provider-badge{display:inline-block;background:#e6f6f2;color:#12675f;padding:8px 12px;border-radius:20px;font-size:13px;font-weight:700}.listing-features{display:flex;flex-wrap:wrap;gap:10px;padding:0;list-style:none}.listing-features li{padding:8px 12px;border:1px solid #dcece9;border-radius:8px}.description{white-space:pre-wrap;overflow-wrap:anywhere}
